from __future__ import annotations; from pathlib import Path; from common.meta.extension.app_boundary import APP_REMAINDER_SUBDIRS, cross_boundary_edges, discover_and_compute_edges, l4_deep_import_edges, load_baseline; REPO_ROOT = Path(__file__).resolve().parents[2]; BASELINE = REPO_ROOT / 'common/meta/data/app-boundary-baseline.json'
def _make_pkg(backend_src: Path, name: str, all_symbols: list[str], internal_body: str='') -> None: pkg = backend_src / name; (pkg / 'extension').mkdir(parents=True, exist_ok=True); (pkg / '__init__.py').write_text(f'__all__ = {all_symbols!r}\n', encoding='utf-8'); (pkg / 'extension' / 'internal.py').write_text(internal_body or 'SECRET = 1\n', encoding='utf-8')
def test_inbound_leak_detected(tmp_path: Path) -> None: src = tmp_path / 'apps/backend/src'; (src / 'services').mkdir(parents=True); _make_pkg(src, 'extraction', ['PublicThing']); (src / 'services' / 'leaky.py').write_text('from src.extraction.extension.internal import SECRET\n', encoding='utf-8'); edges = cross_boundary_edges(backend_src=src, carved={'extraction': 'extraction'}, published={'extraction': {'PublicThing'}}, repo_root=tmp_path); assert any((e.startswith('in::') and 'SECRET' in e for e in edges)); _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); _m1_src = _m1_tmp / 'apps/backend/src'; (_m1_src / 'services').mkdir(parents=True); _make_pkg(_m1_src, 'extraction', ['PublicThing']); (_m1_src / 'services' / 'ok.py').write_text('from src.extraction import PublicThing\n', encoding='utf-8'); _m1_edges = cross_boundary_edges(backend_src=_m1_src, carved={'extraction': 'extraction'}, published={'extraction': {'PublicThing'}}, repo_root=_m1_tmp); assert _m1_edges == []
def test_AC_meta_dependency_governance_3_l4_deep_imports_are_exact(tmp_path: Path) -> None: 'AC-meta.dependency-governance.3'; src = tmp_path / 'apps/backend/src'; (src / 'routers').mkdir(parents=True); (src / 'audit').mkdir(parents=True); (src / 'routers' / 'reports.py').write_text('from src.audit.money import Money\n', encoding='utf-8'); (src / 'routers' / 'health.py').write_text('from src.audit import Money\n', encoding='utf-8'); assert l4_deep_import_edges(src, {'audit'}) == ['routers/reports.py::from src.audit.money import Money']; (src / 'routers' / 'imports.py').write_text('import src.audit.money\n', encoding='utf-8'); assert l4_deep_import_edges(src, {'audit'}) == ['routers/imports.py::import src.audit.money', 'routers/reports.py::from src.audit.money import Money']; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); _m2_src = _m2_tmp / 'apps/backend/src'; (_m2_src / 'services').mkdir(parents=True); _make_pkg(_m2_src, 'extraction', ['PublicThing']); (_m2_src / 'extraction' / 'extension' / 'reaches_up.py').write_text('from src.services.storage import redact\n', encoding='utf-8'); _m2_edges = cross_boundary_edges(backend_src=_m2_src, carved={'extraction': 'extraction'}, published={'extraction': {'PublicThing'}}, repo_root=_m2_tmp); assert any((_m2_e.startswith('out::') and 'src.services.storage' in _m2_e for _m2_e in _m2_edges)); _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); _m3_src = _m3_tmp / 'apps/backend/src'; (_m3_src / 'database').mkdir(parents=True); _make_pkg(_m3_src, 'ledger', ['Account']); (_m3_src / 'ledger' / 'extension' / 'repo.py').write_text('from src.database import get_session\n', encoding='utf-8'); _m3_edges = cross_boundary_edges(backend_src=_m3_src, carved={'ledger': 'ledger'}, published={'ledger': {'Account'}}, repo_root=_m3_tmp); assert _m3_edges == []
def test_app_remainder_subdirs_are_the_app_domain_logic() -> None: assert APP_REMAINDER_SUBDIRS == frozenset({'services', 'routers', 'prompts'}); _m4_current = set(discover_and_compute_edges(REPO_ROOT)); _m4_baseline = load_baseline(BASELINE); _m4_new = _m4_current - _m4_baseline; assert not _m4_new, 'NEW cross-boundary edge(s) not in baseline (add via --update only to SHRINK):\n' + '\n'.join(sorted(_m4_new)); _m5_current = set(discover_and_compute_edges(REPO_ROOT)); _m5_baseline = load_baseline(BASELINE); _m5_stale = _m5_baseline - _m5_current; assert not _m5_stale, f'baseline has {len(_m5_stale)} stale entries — run --update to prune:\n' + '\n'.join(sorted(_m5_stale)); from common.meta.extension.check_app_boundary import main; assert main(['--repo-root', str(REPO_ROOT)]) == 0
def test_gate_fails_when_a_new_edge_appears(tmp_path: Path, monkeypatch) -> None: import json; from common.meta.extension import check_app_boundary; monkeypatch.setattr(check_app_boundary, 'discover_and_compute_edges', lambda _root: ['in::apps/backend/src/services/new_leak.py::src.extraction.extension.x::SECRET']); (tmp_path / 'common/meta/data').mkdir(parents=True); (tmp_path / 'common/meta/data/app-boundary-baseline.json').write_text(json.dumps([]), encoding='utf-8'); assert check_app_boundary.main(['--repo-root', str(tmp_path)]) == 1
def test_update_refuses_to_grow_an_existing_baseline(tmp_path: Path, monkeypatch) -> None: import json; from common.meta.extension import check_app_boundary; edge = 'in::apps/backend/src/services/x.py::src.extraction.extension.y::Z'; monkeypatch.setattr(check_app_boundary, 'discover_and_compute_edges', lambda _root: [edge]); base = tmp_path / 'common/meta/data/app-boundary-baseline.json'; base.parent.mkdir(parents=True); base.write_text(json.dumps([]), encoding='utf-8'); assert check_app_boundary.main(['--repo-root', str(tmp_path), '--update']) == 1; assert json.loads(base.read_text()) == []; base.unlink(); assert check_app_boundary.main(['--repo-root', str(tmp_path), '--update']) == 0; assert json.loads(base.read_text()) == [edge]
def test_update_refuses_to_grow_an_existing_l4_deep_import_baseline(tmp_path: Path, monkeypatch) -> None: import json; from common.meta.extension import check_app_boundary; edge = 'routers/reports.py::from src.audit.money import Money'; monkeypatch.setattr(check_app_boundary, 'discover_and_compute_edges', lambda _root: []); monkeypatch.setattr(check_app_boundary, 'discover_l4_deep_import_edges', lambda _root: [edge]); data = tmp_path / 'common/meta/data'; data.mkdir(parents=True); (data / 'app-boundary-baseline.json').write_text('[]\n', encoding='utf-8'); l4_baseline = data / 'l4-root-import-baseline.json'; l4_baseline.write_text('[]\n', encoding='utf-8'); assert check_app_boundary.main(['--repo-root', str(tmp_path), '--update']) == 1; assert json.loads(l4_baseline.read_text()) == []; l4_baseline.unlink(); assert check_app_boundary.main(['--repo-root', str(tmp_path), '--update']) == 0; assert json.loads(l4_baseline.read_text()) == [edge]
def test_l4_baseline_new_and_stale_entries_fail(tmp_path: Path, monkeypatch) -> None: from common.meta.extension import check_app_boundary; edge = 'routers/reports.py::from src.audit.money import Money'; monkeypatch.setattr(check_app_boundary, 'discover_and_compute_edges', lambda _root: []); monkeypatch.setattr(check_app_boundary, 'discover_l4_deep_import_edges', lambda _root: [edge]); data = tmp_path / 'common/meta/data'; data.mkdir(parents=True); (data / 'app-boundary-baseline.json').write_text('[]\n', encoding='utf-8'); l4_baseline = data / 'l4-root-import-baseline.json'; l4_baseline.write_text('[]\n', encoding='utf-8'); assert check_app_boundary.main(['--repo-root', str(tmp_path)]) == 1; l4_baseline.write_text('["retired::edge"]\n', encoding='utf-8'); monkeypatch.setattr(check_app_boundary, 'discover_l4_deep_import_edges', lambda _root: []); assert check_app_boundary.main(['--repo-root', str(tmp_path)]) == 1
def test_update_with_zero_debt_preserves_retired_baselines(tmp_path: Path, monkeypatch) -> None: from common.meta.extension import check_app_boundary; monkeypatch.setattr(check_app_boundary, 'discover_and_compute_edges', lambda _root: []); monkeypatch.setattr(check_app_boundary, 'discover_l4_deep_import_edges', lambda _root: []); base = tmp_path / 'common/meta/data/app-boundary-baseline.json'; l4_base = tmp_path / 'common/meta/data/l4-root-import-baseline.json'; assert check_app_boundary.main(['--repo-root', str(tmp_path), '--update']) == 0; assert not base.exists(); assert not l4_base.exists()
